package vn.info.error404labs.bai2;

public class ComparisonDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int v1 = 1;
		int v2 = 2;
		
		System.out.println(v1 == v2);
		System.out.println(v1 != v2);
		System.out.println(v1 > v2);
		System.out.println(v1 < v2);
		System.out.println(v1 <= v2);
		System.out.println((v1 <= v2) && (v1 == v2));
		System.out.println((v1 <= v2) || (v1 == v2));
	}

}
